<script setup lang="ts">
import { ref, onMounted } from 'vue';
import { Plus, Clock3, CalendarDays } from 'lucide-vue-next';
import { api, send, canEdit, minutes, type Shift } from '../api';
import Modal from '../components/Modal.vue';
const shifts = ref<Shift[]>([]), error = ref(''), busy = ref(false), showForm = ref(false);
const form = ref({ name: '', kind: 'FIXED', start: '08:00', end: '17:00', breakMinutes: 60, graceMinutes: 0, flexMinutes: 0, workDays: [1, 2, 3, 4, 5] });
const days = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
const clock = (v: number) => `${String(Math.floor(v / 60)).padStart(2, '0')}:${String(v % 60).padStart(2, '0')}`;
async function load() { try { shifts.value = await api('/shifts'); } catch (e) { error.value = (e as Error).message; } } onMounted(load);
async function save() { busy.value = true; error.value = ''; try { const { start, end, ...input } = form.value; const toMinute = (s: string) => { const [h, m] = s.split(':').map(Number); return h * 60 + m; }; await api('/shifts', send('POST', { ...input, flexMinutes: input.kind === 'SLIDING' ? input.flexMinutes : 0, startMinute: toMinute(start), endMinute: toMinute(end) })); showForm.value = false; await load(); } catch (e) { error.value = (e as Error).message; } finally { busy.value = false; } }
</script>
<template><div class="section-toolbar"><p class="muted">Assign a schedule to each employee in the directory.</p><button v-if="canEdit()" class="button primary" @click="showForm = true; error = ''"><Plus :size="17" /> Create schedule</button></div><p v-if="error && !showForm" class="alert error" role="alert">{{ error }}</p><div class="schedule-grid"><article v-for="s in shifts" :key="s.id" class="panel schedule-card"><div class="schedule-top"><div class="stat-icon green"><Clock3 :size="22" /></div><span class="badge neutral">{{ s.kind === 'NIGHT' ? 'Night shift' : s.kind === 'SLIDING' ? 'Sliding hours' : 'Fixed hours' }}</span></div><h2>{{ s.name }}</h2><div class="schedule-time">{{ clock(s.startMinute) }} <span>—</span> {{ clock(s.endMinute) }}</div><div class="day-pills"><span v-for="(day, i) in days" :key="day" :class="{ selected: s.workDays.includes(i) }">{{ day }}</span></div><dl class="schedule-details"><div><dt>Break</dt><dd>{{ minutes(s.breakMinutes) }}</dd></div><div><dt>Arrival grace</dt><dd>{{ s.graceMinutes }} min</dd></div><div v-if="s.kind === 'SLIDING'"><dt>Arrival flexibility</dt><dd>{{ s.flexMinutes }} min</dd></div></dl><div class="schedule-footer"><CalendarDays :size="15" />{{ s._count?.employees ?? 0 }} assigned employees</div></article></div><div v-if="!shifts.length" class="panel empty-state"><Clock3 :size="32" /><h3>No schedules yet</h3><p>Create regular office hours or a night schedule.</p></div><p class="page-note">Schedules are preserved once created so changes can be reviewed. Create a new schedule and reassign employees when office hours change. Historical schedule snapshots and holiday calendars are pending.</p><Modal v-if="showForm" title="Create work schedule" @close="!busy && (showForm = false)"><form @submit.prevent="save"><p v-if="error" class="alert error" role="alert">{{ error }}</p><label>Schedule name<input v-model="form.name" required maxlength="120" placeholder="Regular office hours" /></label><label>Schedule type<select v-model="form.kind"><option value="FIXED">Fixed hours</option><option value="SLIDING">Sliding hours</option><option value="NIGHT">Night shift (crosses midnight)</option></select></label><div class="form-grid"><label>Start time<input v-model="form.start" type="time" required /></label><label>End time<input v-model="form.end" type="time" required /></label><label>Break (minutes)<input v-model.number="form.breakMinutes" type="number" min="0" max="240" required /></label><label>Arrival grace (minutes)<input v-model.number="form.graceMinutes" type="number" min="0" max="60" required /></label><label v-if="form.kind === 'SLIDING'">Arrival flexibility (minutes)<input v-model.number="form.flexMinutes" type="number" min="0" max="240" required /></label></div><fieldset class="weekday-field"><legend>Working days</legend><label v-for="(day, i) in days" :key="day" class="check-label"><input v-model="form.workDays" :value="i" type="checkbox" />{{ day }}</label></fieldset><p class="muted small-text">Sliding hours extend the arrival window. Required working minutes remain the same. Night shift departures belong to the prior service day through the scheduled end time.</p><div class="modal-actions"><button type="button" class="button secondary" :disabled="busy" @click="showForm = false">Cancel</button><button class="button primary" :disabled="busy">{{ busy ? 'Saving…' : 'Create schedule' }}</button></div></form></Modal></template>
